<?php
namespace App\Http\Controllers\Api\V1;
use App\Enums\BookingStatus; use App\Http\Controllers\Controller; use App\Http\Requests\CreateBookingRequest; use App\Models\Booking; use App\Services\Audit; use Illuminate\Http\{JsonResponse,Request}; use Illuminate\Support\Str;
class BookingController extends Controller { public function index(Request $r):JsonResponse{$q=Booking::query()->with(['quotation','payment'])->latest();$r->user()->role->value==='customer'?$q->where('customer_id',$r->user()->id):($r->user()->role->value==='technician'?$q->where('technician_id',$r->user()->id):null);return response()->json($q->paginate(20));} public function store(CreateBookingRequest $r):JsonResponse{$data=$r->validated();if(!empty($data['technician_id']))abort_unless(\App\Models\User::whereKey($data['technician_id'])->where('role','technician')->whereHas('technicianProfile',fn($q)=>$q->where('kyc_status','approved')->where('is_available',true))->exists(),422,'Selected technician is unavailable or unverified.');$booking=Booking::create($data+['reference'=>'FX-'.now()->format('ymd').'-'.Str::upper(Str::random(6)),'customer_id'=>$r->user()->id,'status'=>BookingStatus::Requested]);Audit::record('booking.created',$booking);return response()->json(['data'=>$booking],201);} public function show(Request $r,Booking $booking):JsonResponse{$this->guard($r,$booking);return response()->json(['data'=>$booking->load(['customer','technician','quotation','evidence','dispute','payment','review'])]);} private function guard(Request $r,Booking $b):void{$u=$r->user();abort_unless($u->role->value==='admin'||$b->customer_id===$u->id||$b->technician_id===$u->id,403);} }
